        'articulos_relacionados' => [],
    ],
    [
        'id' => 'accidente-trabajo-017 CATEGORIA: Accidente de Trabajo PREGUNTA: ¿Qué pasa si el empleador dice que fue un accidente doméstico? RESPUESTA_CORTA: Si ocurrió por el trabajo, podés reclamar y demostrar el origen laboral.',
        'categoria' => 'Accidente de Trabajo',
        'pregunta' => 'Accidente trabajo 017 categoria: accidente de trabajo pregunta: ¿qué pasa si el empleador dice que fue un accidente doméstico? respuesta_corta: si ocurrió por el trabajo, podés reclamar y demostrar el origen laboral.',
        'respuesta_corta' => 'Si ocurrió por el trabajo, podés reclamar y demostrar el origen laboral. ### Pregunta ### Respuesta Corta',
        'respuesta_completa' => '<div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">📌 Accidente laboral: el art. 6 de la LRT protege los accidentes ocurridos con ocasión o en ejercicio del trabajo.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">📄 Pruebas: reuní testigos, fotos, registros de ingreso, cámaras o cualquier evidencia que demuestre dónde ocurrió el accidente.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">✅ Reclamo: si la ART rechaza la cobertura, podés iniciar el trámite ante la Comisión Médica.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">⚠️ Versión del empleador: lo que diga el empleador no determina por sí solo el resultado del reclamo. ⏳ No demores: actuá rápidamente para preservar las pruebas. No aceptes que cambien la versión de los hechos. Si el accidente fue laboral, tenés derecho a la cobertura correspondiente.</div>',
