    [
        'id' => 'accidente-trabajo-024 CATEGORIA: Accidente de Trabajo PREGUNTA: ¿Qué pasa si me cambian el horario después del accidente? RESPUESTA_CORTA: El cambio debe ser razonable y compatible con tu estado de salud.',
        'categoria' => 'Accidente de Trabajo',
